*/

let gol;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	describe("gol glider machine as a texture on a 3D cube");  
	pixelDensity(1);
	frameRate(30);
	gol = new GoL(50, 50, 20);
	// for (let i = 0; i < 48; i++) gol.update();
}

function draw() {
	background(2, 2, 12);
	orbitControl();
	// lights();

	rotateZ(frameCount * 0.01);
  rotateX(frameCount * 0.01);
  rotateY(frameCount * 0.01);

	if (frameCount % 10 === 0) gol.update();
	// gol.show();
	let gr = gol.getGr();
	texture(gr);
	noStroke();

	box(width / 2);
}

class GoL {
	constructor(_dx, _dy, _sz) {
		this.dx = _dx;
		this.dy = _dy;
		this.sz = _sz;
		this.gr = createGraphics(_dx *_sz, _dy *_sz);
		this.init();
	}

	initArr(init = false) {
		let arr = new Array(this.dy);
		for (let i = 0; i < arr.length; i++) {
			arr[i] = new Array(this.dx)
			for (let j = 0; j < arr[i].length; j++) {
				arr[i][j] = 0;
				if (init) arr[i][j] = random() < 0.2 ? 1 : 0;
			}
		}
		return arr;
	}

	init() {
		this.state = this.initArr(false); // true = fill randomly
		this.placeReproductionGliderMachine(this.state, ~~((this.dx-36)/2), ~~((this.dx-9)/3));
		this.nbs = this.initArr();
	}

	placeReproductionGliderMachine(arr, x, y) {
		const reproductionGliderMachine = [
			"                        *           ",
			"                      * *           ",
			"            **      **            **",
			"           *   *    **            **",
			"**        *     *   **              ",
			"**        *   * **    * *           ",
			"          *     *       *           ",
			"           *   *                    ",
			"            **                      ",
		]
		// console.log(reproductionGliderMachine);
		const rgm = reproductionGliderMachine;
		for (let i = 0; i < rgm.length; i++) {
			for (let j = 0; j < rgm[i].length; j++) {
				arr[i+y][j+x] = rgm[i][j] === "*";
			}
		}
	}

	update() {
		// https://en.wikipedia.org/wiki/Conway%27s_Game_of_Life    

		// caclulate the living neighbours
		this.nbs = this.initArr();
		for (let y  = 0; y < this.dy; y++) {
			for (let x = 0; x< this.dx; x++) {
				for (let j  = -1; j <= 1; j++) {
					for (let i  = -1; i <= 1; i++) {
						if (!(i === 0 && j === 0)) {
							const cy = y + j;
							const cx = x + i;
							if (cx < 0 || cx >= this.dx) continue;
							if (cy < 0 || cy >= this.dy) continue;
							if (this.state[cy][cx]) this.nbs[y][x]++;
							/*
							var cy = (y + j + this.dy) % this.dy;
							var cx = (x + i + this.dx) % this.dx;
							if (this.state[cy][cx]) this.nbs[y][x]++;
							*/
						}
					}
				}
			}
		}
		// console.log(this.nbs);

		// 1. Any live cell with two or three live neighbours survives.
    // 2. Any dead cell with three live neighbours becomes a live cell.
    // 3. All other live cells die in the next generation. Similarly, all other dead cells stay dead.
		for (let y  = 0; y < this.dy; y++) {
			for (let x = 0; x< this.dx; x++) {
				/*
				if (this.state[y][x] && this.nbs[y][x] >= 2 && this.nbs[y][x] <= 3) {
					// rule 1.: no action needed, it is alive
					this.state[y][x] = 1;
				} else if (this.state[y][x] === 0 && this.nbs[y][x] === 3) {
					// rule 2: alive dead cells with 3 neighbours
					this.state[y][x] = 1;
				} else {
					// rule 3: die
					this.state[y][x] = 0;
				}
				*/

				if (this.state[y][x] && this.nbs[y][x] == 2 || this.nbs[y][x] == 3) {
					// stay alive
					this.state[y][x] = 1;
				} else if (this.state[y][x] === 0 && this.nbs[y][x] == 3) {
					this.state[y][x] = 1;
				} else {
					this.state[y][x] = 0;
				}

			}
		}

		// end update()
	}

	getGr() {
		// dont do this every time (memory issue): 
		// this.gr = createGraphics(this.dx * this.sz, this.dy * this.sz);
		// instead erase the image 
		this.gr.fill(255);
		this.gr.noStroke();
		this.gr.erase();
		this.gr.rect(0, 0, this.gr.width, this.gr.height);
		this.gr.noErase();
		const clrG = 255 * noise(frameCount * 0.01);
		for (let y  = 0; y < this.dy; y++) {
			for (let x = 0; x< this.dx; x++) {
				this.gr.fill(255, 8)
				if (this.state[y][x]) {
					this.gr.fill(y/this.dy*255, x/this.dx*255, clrG, 255)
					// this.gr.fill(32, 192, 160, 255)
				}
				this.gr.rect(x * this.sz, y * this.sz, this.sz - 1, this.sz - 1);
			}
		}
		return this.gr;
	}

	show() {
		push();
		noStroke()
		textAlign(CENTER, CENTER)
		for (let y  = 0; y < this.dy; y++) {
			for (let x = 0; x< this.dx; x++) {
				fill("blue")
				if (this.state[y][x]) rect(x * this.sz, y * this.sz, this.sz, this.sz);
				fill(255)
				text(this.nbs[y][x], x * this.sz + this.sz * 0.5, y * this.sz+ this.sz * 0.5)
			}
		}
		pop();
	}
}
